use std::time::Duration;

use crate::market::timeframe::Timeframe;

// Default candle settings are shared across the bot. For example...
//
// CandleConfig::default() is currently used in:
// - backtest/runner.rs   -> candle timeframes for backtesting
// - exchange/alpaca.rs   -> candle timeframes for live trading
// - strategy constructors -> candle history retention
//
// Changing the defaults below updates both live and backtest behavior.

#[derive(Debug, Clone)]
pub struct CandleConfig {
    // Candle timeframes generated by both live and backtest modes.
    //
    // To add another timeframe:
    // 1. Create/add the timeframe in timeframe.rs if needed.
    // 2. Add it to this list in CandleConfig::default().
    //
    // Example:
    // Timeframe::THIRTY_MINUTES
    //
    // Every raw trade will automatically update every timeframe
    // listed here through CandleManager.
    pub timeframes: Vec<Timeframe>,

    pub history_retention: Duration,
}

// Add or remove candle timeframes here.
// CandleManager will automatically build all listed timeframes.
impl Default for CandleConfig {
    fn default() -> Self {
        Self {
            // These are the candle timeframes the bot will generate.
            // Add/remove timeframes here to control what is built.
            timeframes: vec![
                Timeframe::ONE_MINUTE,
                Timeframe::FIVE_MINUTES,
                Timeframe::TEN_MINUTES,
                Timeframe::FIFTEEN_MINUTES,
                Timeframe::THIRTY_MINUTES,
                Timeframe::ONE_HOUR,
                Timeframe::TWO_HOURS,
                Timeframe::FOUR_HOURS,
            ],

            history_retention:
                Duration::from_secs(
                    48 * 60 * 60
                ),
        }
    }
}